import{_ as l,I as t,o as n,c as d,b6 as e,j as o,J as i,w as h}from"./chunks/framework.BUXTSoD9.js";const y=JSON.parse('{"title":"生鮮 EC マイクロサービスシステム開発実践","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/stage-2/assignments/simple-grocery-microservices/index.md","filePath":"ja-jp/stage-2/assignments/simple-grocery-microservices/index.md"}'),c={name:"ja-jp/stage-2/assignments/simple-grocery-microservices/index.md"},p={style:{margin:"32px 0"}};function b(g,a,k,u,m,f){const r=t("StepBar"),s=t("ClientOnly");return n(),d("div",null,[a[0]||(a[0]=e('<h1 id="生鮮-ec-マイクロサービスシステム開発実践" tabindex="-1">生鮮 EC マイクロサービスシステム開発実践 <a class="header-anchor" href="#生鮮-ec-マイクロサービスシステム開発実践" aria-label="Permalink to “生鮮 EC マイクロサービスシステム開発実践”">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to “概要”">​</a></h2><p>本実践プロジェクトでは、実際の PRD に基づいて、生鮮 EC マイクロサービスシステムを一から完成させます。これまでの単一サービスプロジェクトとは異なり、このプロジェクトのバックエンドはビジネスごとに複数の独立したサービスに分割され、API ゲートウェイを通じて統一的に外部に公開されます。サービス境界の設計方法や、クロスサービスのデータ整合性の処理方法を学びます。</p><p>これは Stage 2 の総合実践セクションです。マイクロサービスアーキテクチャは実際の業務で非常に一般的であり、サービス分割とゲートウェイルーティングの基本的な考え方を習得すれば、より複雑なバックエンドシステム設計に対応できるようになります。</p><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to “前提知識”">​</a></h2><p>このプロジェクトを始める前に、以下の内容をすでに習得している必要があります：</p><ul><li>フロントエンドページ設計とコンポーネントライブラリの使用（<a href="./../../frontend/ui-design/">UI 設計</a>、<a href="./../../frontend/modern-component-library/">モダンコンポーネントライブラリ</a>）</li><li>バックエンドインターフェース設計と開発（<a href="./../../backend/ai-interface-code/">インターフェースコード作成</a>）</li><li>データベース基礎と Supabase（<a href="./../../backend/database-supabase/">データベースから Supabase まで</a>）</li><li>Git ワークフローとデプロイ（<a href="./../../backend/git-workflow/">Git と GitHub</a>、<a href="./../../backend/zeabur-deployment/">Web アプリのデプロイ</a>）</li></ul><h2 id="学習目標" tabindex="-1">学習目標 <a class="header-anchor" href="#学習目標" aria-label="Permalink to “学習目標”">​</a></h2><p>本実践完了後、以下のことができるようになります：</p><ol><li>PRD を読み、マイクロサービスシステムの開発タスクリストを抽出する</li><li>ビジネスドメインごとにサービス境界を分割する（認証、商品、在庫、注文）</li><li>API ゲートウェイルーティングを設計・実装する</li><li>在庫引き当てや注文整合性などのクロスサービス問題を処理する</li><li>エンドツーエンドの結合テストを完了し、デモ可能なマイクロサービスプロトタイプを納品する</li></ol><h2 id="プロジェクト概要" tabindex="-1">プロジェクト概要 <a class="header-anchor" href="#プロジェクト概要" aria-label="Permalink to “プロジェクト概要”">​</a></h2><p>あなたが構築する製品は、生鮮 EC マイクロサービスシステムです：</p><table tabindex="0"><thead><tr><th>サブシステム</th><th>責務</th></tr></thead><tbody><tr><td><strong>ユーザー側</strong></td><td>商品閲覧、注文、注文確認</td></tr><tr><td><strong>管理側</strong></td><td>商品管理、在庫管理、注文管理</td></tr></tbody></table><p>バックエンドはビジネスごとに以下のサービスに分割されます：</p><table tabindex="0"><thead><tr><th>サービス</th><th>責務</th></tr></thead><tbody><tr><td><strong>API Gateway</strong></td><td>統一エントリ、ルーティング転送、認証チェック</td></tr><tr><td><strong>Auth Service</strong></td><td>ユーザー登録、ログイン、JWT 発行</td></tr><tr><td><strong>Catalog Service</strong></td><td>商品情報管理</td></tr><tr><td><strong>Inventory Service</strong></td><td>在庫数量管理</td></tr><tr><td><strong>Order Service</strong></td><td>注文作成、ステータス管理</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本プロジェクトの要件文書は GitHub にあります： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/ja-jp/stage-2/assignments/simple-grocery-microservices/PRD.md" target="_blank" rel="noreferrer">PRD を表示</a></p></div>',16)),o("div",p,[i(s,null,{default:h(()=>[i(r,{active:0,items:[{title:"要件分析",description:"PRD を読み、サービス分割、ページ、取引フローを明確にする"},{title:"スケルトン構築",description:"フロントエンド、ゲートウェイ、各サービスのスケルトンを生成"},{title:"反復開発",description:"モジュールごとにインターフェースを追加し、在庫と注文の整合性を修正"},{title:"結合とリリース",description:"エンドツーエンドで動作確認し、デプロイしてデモを準備"}]})]),_:1})]),a[1]||(a[1]=e(`<h2 id="第-1-部-要件分析" tabindex="-1">第 1 部：要件分析 <a class="header-anchor" href="#第-1-部-要件分析" aria-label="Permalink to “第 1 部：要件分析”">​</a></h2><h3 id="_1-1-prd-を読む" tabindex="-1">1.1 PRD を読む <a class="header-anchor" href="#_1-1-prd-を読む" aria-label="Permalink to “1.1 PRD を読む”">​</a></h3><p>PRD 文書を開き、以下の質問に重点的に答えてください：</p><ul><li>サービスはどのように分割しますか？各サービスの責任境界は何ですか？</li><li>フロントエンドと管理側にはそれぞれどのページがありますか？</li><li>注文後の在庫引き当ての戦略は何ですか？成功/失敗/タイムアウトの各ケースにどう対応しますか？</li><li>第 1 版では、どの複雑な機能（分散トランザクション、メッセージキューなど）を先送りにしますか？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>以上の質問に対する明確な答えがない場合は、コードを書き始めないでください。要件の理解が不明確なのは、手戻りの最も一般的な原因です。</p></div><h3 id="_1-2-システムアーキテクチャの確認" tabindex="-1">1.2 システムアーキテクチャの確認 <a class="header-anchor" href="#_1-2-システムアーキテクチャの確認" aria-label="Permalink to “1.2 システムアーキテクチャの確認”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; fe[&quot;フロントエンドページ&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  fe --&gt; gw[&quot;API Gateway&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; auth[&quot;Auth Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; catalog[&quot;Catalog Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; inventory[&quot;Inventory Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; order[&quot;Order Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  order --&gt; inventory</span></span></code></pre></div><h2 id="第-2-部-プロジェクトスケルトンの構築" tabindex="-1">第 2 部：プロジェクトスケルトンの構築 <a class="header-anchor" href="#第-2-部-プロジェクトスケルトンの構築" aria-label="Permalink to “第 2 部：プロジェクトスケルトンの構築”">​</a></h2><h3 id="_2-1-プロジェクト構造の生成" tabindex="-1">2.1 プロジェクト構造の生成 <a class="header-anchor" href="#_2-1-プロジェクト構造の生成" aria-label="Permalink to “2.1 プロジェクト構造の生成”">​</a></h3><p>プロンプト参考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>現在の PRD に基づいて、生鮮 EC マイクロサービスシステムのプロジェクトスケルトンを生成してください。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要件：</span></span>
<span class="line"><span>1. フロントエンドのユーザー側と管理側のスケルトンを生成</span></span>
<span class="line"><span>2. api-gateway、auth-service、catalog-service、inventory-service、order-service の 5 つのディレクトリを生成</span></span>
<span class="line"><span>3. 各サービスはまず最小限の実行可能エントリのみを作成</span></span>
<span class="line"><span>4. 実際のデータベースと決済はまだ接続しない</span></span></code></pre></div><h3 id="_2-2-プロジェクト構造の検証" tabindex="-1">2.2 プロジェクト構造の検証 <a class="header-anchor" href="#_2-2-プロジェクト構造の検証" aria-label="Permalink to “2.2 プロジェクト構造の検証”">​</a></h3><p>項目ごとにチェック：</p><ul><li>[ ] 5 つのサービスディレクトリ構造が明確</li><li>[ ] API Gateway が起動してリクエストを転送できる</li><li>[ ] 各サービスのヘルスチェックインターフェースが利用可能</li><li>[ ] フロントエンドのユーザー側と管理側ページがアクセス可能</li></ul><h2 id="第-3-部-反復開発" tabindex="-1">第 3 部：反復開発 <a class="header-anchor" href="#第-3-部-反復開発" aria-label="Permalink to “第 3 部：反復開発”">​</a></h2><h3 id="_3-1-モジュールごとに進める" tabindex="-1">3.1 モジュールごとに進める <a class="header-anchor" href="#_3-1-モジュールごとに進める" aria-label="Permalink to “3.1 モジュールごとに進める”">​</a></h3><ol><li><strong>API Gateway</strong>：ルーティング設定、JWT 検証ミドルウェア</li><li><strong>Auth Service</strong>：登録、ログイン、JWT 発行</li><li><strong>Catalog Service</strong>：商品 CRUD、リストクエリ</li><li><strong>Inventory Service</strong>：在庫照会、在庫引き当て</li><li><strong>Order Service</strong>：注文作成、ステータス遷移、在庫連動</li><li><strong>管理側</strong>：商品管理、在庫管理、注文管理</li></ol><h3 id="_3-2-モジュール自己チェック" tabindex="-1">3.2 モジュール自己チェック <a class="header-anchor" href="#_3-2-モジュール自己チェック" aria-label="Permalink to “3.2 モジュール自己チェック”">​</a></h3><table tabindex="0"><thead><tr><th>チェック項目</th><th>検証方法</th></tr></thead><tbody><tr><td>ゲートウェイルーティング</td><td>各サービスのインターフェースがゲートウェイ経由で正しく転送されているか</td></tr><tr><td>権限分離</td><td>ユーザー側と管理側のインターフェースが分離されているか</td></tr><tr><td>データ整合性</td><td>商品と在庫のデータが同期しているか</td></tr><tr><td>取引クロージャ</td><td>注文後の在庫引き当て、注文ステータスが一致しているか</td></tr><tr><td>障害処理</td><td>在庫不足やタイムアウト時に補償メカニズムがあるか</td></tr></tbody></table><h2 id="第-4-部-結合テストとリリース" tabindex="-1">第 4 部：結合テストとリリース <a class="header-anchor" href="#第-4-部-結合テストとリリース" aria-label="Permalink to “第 4 部：結合テストとリリース”">​</a></h2><h3 id="_4-1-エンドツーエンドテスト" tabindex="-1">4.1 エンドツーエンドテスト <a class="header-anchor" href="#_4-1-エンドツーエンドテスト" aria-label="Permalink to “4.1 エンドツーエンドテスト”">​</a></h3><p>少なくとも以下のシナリオを検証：</p><ul><li>商品を閲覧 → カートに追加 → 注文 → 注文確認</li><li>管理者 → 商品を追加 → 在庫を更新 → 注文確認</li></ul><h2 id="提出物" tabindex="-1">提出物 <a class="header-anchor" href="#提出物" aria-label="Permalink to “提出物”">​</a></h2><p>本プロジェクト完了後、以下の内容を提出する必要があります：</p><ul><li>[ ] アクセス可能なオンラインデモリンク</li><li>[ ] ソースコードリポジトリリンク（README を含む）</li><li>[ ] PRD 文書</li><li>[ ] コアページのスクリーンショット（商品リスト、注文ページ、注文ページ、管理バックエンド）</li><li>[ ] 60 秒のデモ動画</li></ul><h2 id="評価基準" tabindex="-1">評価基準 <a class="header-anchor" href="#評価基準" aria-label="Permalink to “評価基準”">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>基本要件</th><th>応用要件</th></tr></thead><tbody><tr><td>PRD 整合性</td><td>ページ、機能、サービス分割が基本的に PRD に適合</td><td>サービス分割の理由を明確に説明できる</td></tr><tr><td>製品クロージャ</td><td>閲覧 → 注文 → 在庫引き当て → 注文確認が動作する</td><td>注文タイムアウトや在庫不足時に補償メカニズムがある</td></tr><tr><td>サービスアーキテクチャ</td><td>各サービスが独立して起動でき、ゲートウェイ経由で統一アクセス可能</td><td>サービス間通信にエラー処理とリトライがある</td></tr><tr><td>管理機能</td><td>商品、在庫、注文管理が操作可能</td><td>管理側にデータ統計がある</td></tr><tr><td>エンジニアリング完成度</td><td>フロントエンド、ゲートウェイ、サービス、データベースのパイプラインが接続されている</td><td>Docker Compose などのオーケストレーションがある</td></tr></tbody></table><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to “参考資料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 設計</a></li><li><a href="./../../frontend/modern-component-library/">モダンコンポーネントライブラリでインターフェースを更新</a></li><li><a href="./../../backend/database-supabase/">データベースから Supabase まで</a></li><li><a href="./../../backend/ai-interface-code/">大規模モデルによるインターフェースコードとドキュメント作成</a></li><li><a href="./../../backend/git-workflow/">Git と GitHub ワークフロー</a></li><li><a href="./../../backend/zeabur-deployment/">Web アプリのデプロイ方法</a></li></ul>`,30))])}const P=l(c,[["render",b]]);export{y as __pageData,P as default};
